// Глобальный обработчик ошибок (AC-6.3).
// Скелет: логируем детали упавшего воркфлоу. В Фазе 5/7 сюда добавим
// реальный алерт (email/VK/Telegram).
const err = $json;
const wf = err.workflow || {};
const exec = err.execution || {};
console.error('[WF0] Workflow failed:', JSON.stringify({
  workflow: wf.name || wf.id,
  executionId: exec.id,
  lastNode: exec.lastNodeExecuted,
  message: (exec.error && exec.error.message) || err.message
}));
return [{ json: { handled: true, workflow: wf.name, message: (exec.error && exec.error.message) || null } }];
